import{_ as o,o as d,c as t,a3 as a}from"./chunks/framework.cNy3aYYk.js";const u=JSON.parse('{"title":"Calendar — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Calendar — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/calendar"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Calendar — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/calendar"}]]},"headers":[],"relativePath":"developer-guide/calendar.md","filePath":"developer-guide/calendar.md","lastUpdated":1791153118000}'),c={name:"developer-guide/calendar.md"};function n(r,e,i,s,l,p){return d(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="calendar-—-developer-guide" tabindex="-1">Calendar — Developer Guide <a class="header-anchor" href="#calendar-—-developer-guide" aria-label="Permalink to &quot;Calendar — Developer Guide&quot;">​</a></h1><blockquote><p><strong>Status: Implemented (v1)</strong><br> Meetings depends on Calendar (required) and projects via <code>upsertFromSource</code>. No calendar assignment in v1.</p></blockquote><h2 id="ownership" tabindex="-1">Ownership <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;Ownership&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>Owner</th></tr></thead><tbody><tr><td><code>calendar_events</code> table / CRUD / Week·Day·Month·Agenda UI</td><td>Calendar module</td></tr><tr><td>Meeting booking, host assignment, Zoom/Meet, reminders</td><td><a href="/developer-guide/meetings">Meetings</a> module (calls <code>CalendarEventService</code>)</td></tr></tbody></table><h2 id="model" tabindex="-1">Model <a class="header-anchor" href="#model" aria-label="Permalink to &quot;Model&quot;">​</a></h2><p><code>App\\Models\\CalendarEvent</code> — <code>BelongsToTenant</code>, <code>LogsActivity</code>, <code>SoftDeletes</code>.</p><p>Key fields: <code>organizer_id</code>, <code>starts_at</code>, <code>ends_at</code>, <code>all_day</code>, <code>timezone</code>, <code>status</code> (<code>scheduled</code>|<code>cancelled</code>), <code>source</code> (<code>manual</code>|<code>meeting</code>|<code>project</code>|<code>task</code>|<code>lead</code>), nullable <code>source_type</code>/<code>source_id</code> (Meetings uses morph alias <code>meeting</code>; Projects/Tasks/Leads use <code>project</code> / <code>task</code> / <code>lead</code>), nullable <code>external_provider</code> (<code>google</code>|<code>microsoft</code>) / <code>external_event_id</code> (Calendar sync mapping — <strong>1.4.0</strong>).</p><p><strong>Excluded:</strong> <code>assignee_id</code>, named team calendars, two-way Google/Outlook sync, pushing sourced overlays.</p><h2 id="visibility" tabindex="-1">Visibility <a class="header-anchor" href="#visibility" aria-label="Permalink to &quot;Visibility&quot;">​</a></h2><ul><li>Without <code>calendar.view_all</code>: <code>organizer_id = actor</code> <strong>or</strong> meeting projection where the actor is a <code>meeting_attendees.user_id</code> row for <code>source_type=meeting</code> / <code>source_id</code></li><li>With <code>calendar.view_all</code> or Owner superadmin: all tenant events</li><li>Update / cancel / delete remain organizer-only (or <code>view_all</code> / superadmin) — invitees are read-only</li><li>Resource includes <code>read_only: true</code> when the viewer is not the organizer and lacks <code>view_all</code></li><li><code>POST</code> always sets <code>organizer_id</code> to the authenticated user; <code>organizer_id</code> / <code>assignee_id</code> are <strong>prohibited</strong> on requests</li></ul><h2 id="service-contract-meetings-ready" tabindex="-1">Service contract (Meetings-ready) <a class="header-anchor" href="#service-contract-meetings-ready" aria-label="Permalink to &quot;Service contract (Meetings-ready)&quot;">​</a></h2><p><code>App\\Services\\Tenant\\CalendarEventService</code>:</p><ul><li><code>createForOrganizer</code>, <code>update</code>, <code>cancel</code>, <code>delete</code></li><li><code>listInRange</code>, <code>upcoming</code></li><li><code>upsertFromSource</code> — used by Meetings, Projects, Tasks, and Leads; unused by Calendar UI for create</li></ul><h2 id="overlays-1-1-0" tabindex="-1">Overlays (1.1.0) <a class="header-anchor" href="#overlays-1-1-0" aria-label="Permalink to &quot;Overlays (1.1.0)&quot;">​</a></h2><p>When Calendar is entitled:</p><table tabindex="0"><thead><tr><th>Source</th><th>Projector</th><th>Projection</th></tr></thead><tbody><tr><td><code>meeting</code></td><td>Meetings</td><td>Host event</td></tr><tr><td><code>project</code></td><td>Projects</td><td>All-day on <code>starts_on</code> / <code>ends_on</code></td></tr><tr><td><code>task</code></td><td>Tasks</td><td>Timed window from <code>due_at</code> (+1h); cleared when completed/cancelled/no due</td></tr><tr><td><code>lead</code></td><td>Leads</td><td>Timed window from <code>next_follow_up_at</code> (+1h); cleared when converted/closed/archived/no follow-up</td></tr></tbody></table><p>Catalog version <strong>1.1.0</strong> (overlays). <strong>1.2.0</strong> adds invitee list/view ACL for meeting projections. <strong>1.3.0</strong> adds event-level shares (<code>viewer</code>/<code>editor</code>) for manual events. <strong>1.4.0</strong> adds Google/Outlook sync Phase 1 (below). Pest: <code>TaskLeadCalendarOverlayTest.php</code>, <code>MeetingInviteeCalendarAclTest.php</code>, <code>CalendarEventShareTest.php</code>.</p><h2 id="google-outlook-sync-1-4-0" tabindex="-1">Google / Outlook sync (1.4.0) <a class="header-anchor" href="#google-outlook-sync-1-4-0" aria-label="Permalink to &quot;Google / Outlook sync (1.4.0)&quot;">​</a></h2><p>Per-user, one-way (EloSync → provider) push for <strong>manual</strong> events only. Mirrors the Meetings Google Meet OAuth pattern, but connections are <strong>per user</strong> (not per tenant) and credentials are <strong>platform env-based</strong> (not stored per tenant).</p><table tabindex="0"><thead><tr><th>Concept</th><th>Owner</th></tr></thead><tbody><tr><td>Config</td><td><code>config/calendar-sync.php</code> — <code>google.client_id/secret</code>, <code>microsoft.client_id/secret/tenant</code>, <code>oauth_callback_path</code>, <code>providers.fake</code></td></tr><tr><td>Connection model</td><td><code>App\\Models\\CalendarProviderConnection</code> (<code>BelongsToTenant</code>, <code>SoftDeletes</code>) — <code>tenant_id</code>, <code>user_id</code>, <code>provider</code> (<code>CalendarSyncProviderEnum</code>: <code>google</code>|<code>microsoft</code>), encrypted <code>access_token</code>/<code>refresh_token</code>, <code>expires_at</code>, <code>status</code> (<code>CalendarProviderConnectionStatusEnum</code>), <code>external_calendar_id</code>, <code>meta</code> json</td></tr><tr><td>Providers</td><td><code>App\\Services\\CalendarSync\\Providers\\GoogleCalendarProvider</code>, <code>MicrosoftCalendarProvider</code> — implement <code>CalendarSyncProviderInterface</code> (<code>authorizationUrl</code>, <code>exchangeCode</code>, <code>refreshAccessToken</code>, <code>pushEvent</code>, <code>updateEvent</code>, <code>cancelEvent</code>); driver resolution via <code>CalendarSyncProviderRegistry</code></td></tr><tr><td>Orchestration</td><td><code>App\\Services\\Tenant\\CalendarSyncService</code> — <code>statusForUser</code>, <code>hasPlatformCredentials</code>, <code>authorizationUrl</code>, <code>disconnect</code>, <code>pushEvent($event, $action)</code></td></tr><tr><td>Controller</td><td><code>App\\Http\\Controllers\\Tenant\\Api\\V1\\CalendarIntegrationController</code> — <code>index</code> (status), <code>authorizeProvider</code> (redirect URL), <code>disconnect</code>; web OAuth <code>callback</code> lives on <code>routes/web.php</code> (no tenant auth on the callback route itself, nonce-verified)</td></tr><tr><td>Queue job</td><td><code>App\\Jobs\\Tenant\\PushCalendarEventToProviderJob</code> (<code>calendar-sync</code> queue, <code>tries=3</code>, <code>backoff=[5,30,120]</code>) — dispatched from <code>CalendarEventSubscriber</code> on create/update/cancel/delete, <strong>skipped when <code>source !== manual</code></strong></td></tr></tbody></table><p>Routes (tenant, <code>can:calendar.manage_integrations</code>):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET    /calendar/integrations              status per provider for the authenticated user</span></span>\n<span class="line"><span>GET    /calendar/integrations/{provider}/authorize   OAuth authorize URL</span></span>\n<span class="line"><span>DELETE /calendar/integrations/{provider}   disconnect</span></span></code></pre></div><p>Web (platform, no tenant scope on the route itself):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/oauth/calendar-sync/{provider}/callback   OAuth callback, redirects to `/#/calendar?integrations=…`</span></span></code></pre></div><p><strong>Push behavior:</strong></p><ul><li>Pushes to <strong>every</strong> connected provider for the event&#39;s organizer (a user may connect both Google and Microsoft).</li><li><code>created</code> always calls <code>pushEvent()</code> on the driver (never <code>updateEvent()</code>), even if <code>external_event_id</code> is already set from a different provider.</li><li><code>updated</code> calls <code>updateEvent()</code> only when the connection&#39;s provider matches the currently-stored <code>external_provider</code>; otherwise it treats the connection as unsynced and calls <code>pushEvent()</code>.</li><li><code>cancelled</code>/<code>deleted</code> calls <code>cancelEvent()</code> only against the mapped provider.</li><li><strong>Known Phase-1 limitation:</strong> <code>external_provider</code>/<code>external_event_id</code> on <code>calendar_events</code> is a single-value mapping, not per-provider. If a user has both Google and Microsoft connected, only the last-written provider&#39;s ID is persisted, so update/cancel is only guaranteed to reach the most-recently-synced provider — see the <a href="/deployment/calendar-google-outlook-sync-1-4-0-production-readiness">production readiness audit</a>.</li><li>Failures are caught, <code>report()</code>-ed, and logged (<code>calendar-sync.push-failed</code>) — a broken provider connection never blocks calendar writes (mirrors <code>LiveChatConversationService</code>&#39;s soft-fail pattern).</li><li><code>GoogleCalendarProvider</code>/<code>MicrosoftCalendarProvider</code> expose a <code>fake()</code> escape hatch that is forced on in <code>testing</code> (and never enabled in <code>production</code>), so Pest never makes real HTTP calls even without <code>Http::fake()</code>.</li></ul><p><strong>Excluded:</strong> <code>assignee_id</code>, named team calendars, two-way (inbound) sync, pushing Meeting/Task/Lead/Project/Contact/Company overlays, Customer Portal visibility.</p><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Location</th></tr></thead><tbody><tr><td>Page</td><td><code>src/pages/calendar/calendar-page.tsx</code></td></tr><tr><td>Time grid (Week/Day + DnD)</td><td><code>src/pages/calendar/calendar-time-grid.tsx</code> (<code>@dnd-kit/core</code>)</td></tr><tr><td>Form / detail</td><td><code>calendar-event-form-dialog.tsx</code>, <code>calendar-event-detail-sheet.tsx</code></td></tr><tr><td>Datetime helpers</td><td><code>src/lib/datetime.ts</code> (<code>appTimezone</code>, <code>moveEventToSlot</code>, …)</td></tr><tr><td>API</td><td><code>calendarService</code> in <code>src/api/services.ts</code></td></tr><tr><td>E2E</td><td><code>e2e/tests/calendar/</code>, <code>npm run test:e2e:calendar</code></td></tr></tbody></table><p>Drag-and-drop on Week/Day calls <code>PUT /calendar/events/{id}</code> with new <code>starts_at</code> / <code>ends_at</code> (15-minute snap). Display and inputs use the workspace timezone from settings. <code>starts_at</code> / <code>ends_at</code> / <code>cancelled_at</code> use <code>UtcDateTime</code> + <code>UtcIso</code> so non-UTC workspace timezones do not shift absolute instants.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Configured in <code>config/tenant-permissions.php</code> + default role map:</p><table tabindex="0"><thead><tr><th>Role</th><th>Grants</th></tr></thead><tbody><tr><td>admin</td><td>all including <code>view_all</code> and <code>manage_integrations</code></td></tr><tr><td>manager</td><td>all except <code>delete</code>; includes <code>view_all</code>; no <code>manage_integrations</code></td></tr><tr><td>staff</td><td><code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code> (own only via policy); no <code>view_all</code>, no <code>manage_integrations</code></td></tr></tbody></table><p><code>manage_integrations</code> (Calendar sync connect/disconnect) is admin-only, mirroring Meetings&#39; <code>manage_integrations</code>.</p><h2 id="registration" tabindex="-1">Registration <a class="header-anchor" href="#registration" aria-label="Permalink to &quot;Registration&quot;">​</a></h2><p>Migrate-only:</p><ul><li><code>2026_07_20_230514_create_calendar_events_table.php</code></li><li><code>2026_07_21_040000_register_calendar_module.php</code></li><li><code>2026_07_21_040001_add_calendar_permissions.php</code></li><li><code>2026_09_30_150000_create_calendar_provider_connections_table.php</code></li><li><code>2026_09_30_150001_add_external_provider_to_calendar_events_table.php</code> (adds <code>external_provider</code>/<code>external_event_id</code>, unique index on tenant+provider+external id)</li><li><code>2026_09_30_150002_add_calendar_manage_integrations_permission.php</code></li><li><code>2026_09_30_150003_bump_calendar_module_version_to_1_4_0.php</code></li></ul><p>Also listed in <code>CatalogSeeder</code> for fresh/local/CI.</p><h2 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h2><p><code>DashboardWidgetService</code> registers widget id <code>calendar</code> (upcoming events), gated by <code>module:calendar</code> + <code>calendar.view</code>, scoped by <code>calendar.view_all</code>.</p><h2 id="audit-activity" tabindex="-1">Audit &amp; activity <a class="header-anchor" href="#audit-activity" aria-label="Permalink to &quot;Audit &amp; activity&quot;">​</a></h2><ul><li>Spatie <code>LogsActivity</code> on <code>CalendarEvent</code> records attribute changes.</li><li><code>App\\Listeners\\CalendarEventSubscriber</code> (registered in <code>AppServiceProvider</code>) writes platform audit entries (<code>activity</code> log name <code>platform</code>) for <code>calendar_event_created|updated|cancelled|deleted</code>, mirroring Leads/Tasks/Communication Templates.</li></ul><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><ul><li>Pest: <code>tests/Feature/Tenant/Calendar/CalendarEventTest.php</code>, <code>MeetingInviteeCalendarAclTest.php</code>, <code>CalendarIntegrationTest.php</code>, <code>CalendarEventProviderPushTest.php</code></li><li>Playwright: <code>npm run test:e2e:calendar</code> (includes invitee view-only)</li></ul><h2 id="explicit-non-goals-v1" tabindex="-1">Explicit non-goals (v1) <a class="header-anchor" href="#explicit-non-goals-v1" aria-label="Permalink to &quot;Explicit non-goals (v1)&quot;">​</a></h2><p>Assignment, named team calendars / department auto-share, two-way (inbound) Google/Outlook sync, pushing Meeting/Task/Lead overlays to providers. Meetings/Zoom/Meet live in the Meetings module.</p>',46)])])}const g=o(c,[["render",n]]);export{u as __pageData,g as default};
